				}
			}
		}
		return result;
	}

	/* @Override */
	public List<Long> getReversedSnaps() {
		List<Long> result = new();
		using (LockHold hold = trace.lockRead())
{
			lock (ordered) {
				ListIterator<Lifespan> it = ordered.listIterator(ordered.size());
